package dev.thillainirmal.commercepilot;
import com.fasterxml.jackson.databind.JsonNode; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.web.client.RestClient; import java.util.*;
@Service
public class CommerceExecutionService {
 private final RestClient http;private final String inventoryUrl,paymentUrl,fulfillmentUrl,serviceToken,approvalToken;
 public CommerceExecutionService(RestClient.Builder builder,@Value("${commerce.adapters.inventory-url:}")String inventoryUrl,@Value("${commerce.adapters.payment-url:}")String paymentUrl,@Value("${commerce.adapters.fulfillment-url:}")String fulfillmentUrl,@Value("${commerce.adapters.service-token:}")String serviceToken,@Value("${commerce.approval-token:}")String approvalToken){this.http=builder.build();this.inventoryUrl=inventoryUrl;this.paymentUrl=paymentUrl;this.fulfillmentUrl=fulfillmentUrl;this.serviceToken=serviceToken;this.approvalToken=approvalToken;}
 public Execution execute(OrderOrchestrator.Order order,OrderOrchestrator.Decision decision,String suppliedApproval){if(!"APPROVED".equals(decision.status()))throw new IllegalStateException("Only an approved plan can execute");if(approvalToken.isBlank()||!java.security.MessageDigest.isEqual(approvalToken.getBytes(java.nio.charset.StandardCharsets.UTF_8),String.valueOf(suppliedApproval).getBytes(java.nio.charset.StandardCharsets.UTF_8)))throw new SecurityException("Valid human approval token required");configured();String key=decision.orderId();JsonNode reservation=post(inventoryUrl+"/reservations",Map.of("sku",order.sku(),"quantity",order.quantity(),"orderId",key),key);String reservationId=required(reservation,"id");try{JsonNode payment=post(paymentUrl+"/authorizations",Map.of("customerId",order.customerId(),"amount",decision.total(),"orderId",key),key);JsonNode shipment=post(fulfillmentUrl+"/shipments",Map.of("reservationId",reservationId,"orderId",key),key);return new Execution(key,"EXECUTED",reservationId,required(payment,"id"),required(shipment,"id"));}catch(RuntimeException failure){post(inventoryUrl+"/reservations/"+reservationId+"/release",Map.of("reason","downstream failure","orderId",key),key+"-release");throw failure;}}
 private JsonNode post(String uri,Object body,String key){return http.post().uri(uri).header("Authorization","Bearer "+serviceToken).header("Idempotency-Key",key).body(body).retrieve().body(JsonNode.class);}private String required(JsonNode n,String field){if(n==null||n.path(field).asText().isBlank())throw new IllegalStateException("Adapter response missing "+field);return n.path(field).asText();}private void configured(){if(inventoryUrl.isBlank()||paymentUrl.isBlank()||fulfillmentUrl.isBlank()||serviceToken.isBlank())throw new IllegalStateException("Commerce adapters are not configured");}
 public record Execution(String orderId,String status,String reservationId,String paymentAuthorizationId,String shipmentId){}
}
